import { afterAll, expect, test } from 'vitest'
import { getPlatformProxy } from 'wrangler'
import server from '../../server'
import { TEST_ORIGIN, testEnv } from '../publication/test-support'
import { japaneseOutside } from './test-japanese'

// The pages are generated by `pnpm build`; CI builds before testing.
const platform = await getPlatformProxy<Env>({ persist: false })
const env = testEnv(platform.env)
afterAll(() => platform.dispose())

const get = (path: string, headers: Record<string, string> = {}) =>
  server.fetch(new Request(`${TEST_ORIGIN}${path}`, { headers }), env)

const english = { 'Accept-Language': 'en' }

test.each([
  [{}, 'ja', '<h1>さわって、わかる。</h1>'],
  [english, 'en', '<h1>Touch it, get it.</h1>'],
  [{ Cookie: 'language=en' }, 'en', '<h1>Touch it, get it.</h1>'],
] as const)(
  'Given a request with %j, When the top page opens, Then it is the %s page',
  async (headers, lang, heading) => {
    const response = await get('/', headers)
    expect(response.status).toBe(200)
    expect(response.headers.get('Content-Security-Policy')).toContain(
      "connect-src 'self'",
    )
    const page = await response.text()
    expect(page).toContain(`<html lang="${lang}">`)
    expect(page).toContain(heading)
    expect(page).toMatch(/bf-s="RecentDecks_[^"]+"/)
  },
)

test.each([
  ['/?lang=ja', '合計 7.5s'],
  ['/?lang=en', '7.5s in total'],
])(
  'Given the built top page %s, When read before any script runs, Then the demo shows its starting values',
  async (path, total) => {
    const page = await (await get(path)).text()
    expect(page).toMatch(/bf-s="BackoffDemo_[^"]+"/)
    const demo = page.slice(page.indexOf('bf-s="BackoffDemo_'))
    expect(demo).toContain(total)
    const timeline = demo.slice(0, demo.indexOf('</ol>'))
    expect(timeline.match(/<li\b/g)).toHaveLength(5)
    expect(demo).toMatch(
      /type="range"[^>]*value="2"|value="2"[^>]*type="range"/,
    )
  },
)

test('Given the English top page, When rendered, Then no Japanese is left but the switcher label', async () => {
  const page = await (await get('/?lang=en')).text()
  expect(japaneseOutside(page)).toEqual([])
  expect(page).toContain('href="/?lang=ja"')
})

test('Given a top page seen in one language, When revalidated in each, Then only the same language answers 304', async () => {
  const ja = (await get('/')).headers.get('ETag') ?? ''
  const en = (await get('/', english)).headers.get('ETag') ?? ''
  expect(ja).not.toBe('')
  expect(en).not.toBe('')
  expect(en).not.toBe(ja)
  expect((await get('/', { 'If-None-Match': ja })).status).toBe(304)
  expect((await get('/', { ...english, 'If-None-Match': en })).status).toBe(304)
  const switched = await get('/', { ...english, 'If-None-Match': ja })
  expect(switched.status).toBe(200)
  expect(await switched.text()).toContain('<html lang="en">')
  const byCookie = await get('/', {
    Cookie: 'language=en',
    'If-None-Match': ja,
  })
  expect(byCookie.status).toBe(200)
  expect(byCookie.headers.get('ETag')).toBe(en)
})

test.each([200, 304])(
  'Given the top page answers %i, Then caches keep each language apart',
  async (status) => {
    const etag = (await get('/', english)).headers.get('ETag') ?? ''
    const response = await get(
      '/',
      status === 304 ? { ...english, 'If-None-Match': etag } : english,
    )
    expect(response.status).toBe(status)
    expect(response.headers.get('Vary')).toBe('Accept-Language, Cookie')
  },
)

test('Given a HEAD request in English, When answered, Then it carries the English page ETag', async () => {
  const en = (await get('/', english)).headers.get('ETag')
  const head = await server.fetch(
    new Request(`${TEST_ORIGIN}/`, { method: 'HEAD', headers: english }),
    env,
  )
  expect(head.status).toBe(200)
  expect(head.headers.get('ETag')).toBe(en)
})

test.each(['/_home/en/', '/_home/en/index.html', '/_home/en', '/_home'])(
  'Given the generated page path %s, When requested directly, Then it is not served without the page headers',
  async (path) => {
    const response = await get(path)
    expect(response.status).toBe(404)
    expect(response.headers.get('Content-Security-Policy')).toContain(
      "default-src 'none'",
    )
  },
)
